    margin-top:1rem;
    font-size:.88rem;
  }
  .card .highlight-box p{color:var(--accent-amber);font-weight:500}

  /* ── Hero section ── */
  .hero{min-height:100vh;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center}
  .hero h1{
    font-size:clamp(2.2rem,5vw,3.8rem);font-weight:800;
    background:linear-gradient(135deg,var(--accent-blue),var(--accent-cyan),var(--accent-purple));
    -webkit-background-clip:text;-webkit-text-fill-color:transparent;
    background-clip:text;
    margin-bottom:.6rem;line-height:1.2;
  }
  .hero .subtitle{
    font-size:clamp(1rem,2vw,1.4rem);color:var(--text-dim);
