    --border:#1e293b;
    --text:#e2e8f0;
    --text-dim:#94a3b8;
    --accent-crust:#a3e635;
    --accent-mantle:#fb923c;
    --accent-outer:#f97316;
    --accent-inner:#ef4444;
    --glow-crust:rgba(163,230,53,.15);
    --glow-mantle:rgba(251,146,60,.15);
    --glow-outer:rgba(249,115,22,.15);
    --glow-inner:rgba(239,68,68,.15);
  }

  html{scroll-behavior:smooth;font-size:16px}

  body{
    font-family:'Segoe UI',Tahoma,Arial,sans-serif;
    background:var(--bg-deep);
    color:var(--text);
    line-height:1.9;
    min-height:100vh;
    overflow-x:hidden;
    direction:rtl;
  }

  /* ── Animated background ── */
  body::before{
    content:'';position:fixed;inset:0;z-index:0;pointer-events:none;
    background:
      radial-gradient(ellipse 50% 30% at 50% 100%,rgba(239,68,68,.08),transparent),
      radial-gradient(ellipse 60% 40% at 30% 80%,rgba(249,115,22,.06),transparent),
      radial-gradient(ellipse 40% 30% at 70% 60%,rgba(251,146,60,.05),transparent);
  }

  .stars{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
  .stars span{
    position:absolute;border-radius:50%;background:#fff;
    animation:twinkle var(--dur,4s) ease-in-out infinite var(--delay,0s);
  }
  @keyframes twinkle{0%,100%{opacity:.2;transform:scale(1)}50%{opacity:.8;transform:scale(1.4)}}

  /* ── Header ── */
  header{
    position:sticky;top:0;z-index:100;
    background:rgba(10,10,26,.9);
    backdrop-filter:blur(20px);
    border-bottom:1px solid var(--border);
    padding:1rem 2rem;
    display:flex;align-items:center;justify-content:center;gap:1rem;
  }
  header h1{
    font-size:1.2rem;font-weight:700;
    background:linear-gradient(135deg,var(--accent-crust),var(--accent-mantle),var(--accent-inner));
    -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  }
  header .subtitle{font-size:.8rem;color:var(--text-dim)}

  /* ── Nav dots ── */
  .nav-dots{
    position:fixed;left:1.5rem;top:50%;transform:translateY(-50%);
    z-index:90;display:flex;flex-direction:column;gap:1rem;
  }
  .nav-dots a{
    width:10px;height:10px;border-radius:50%;
    background:var(--border);border:2px solid transparent;
    transition:.3s;display:block;
  }
  .nav-dots a.active{
    background:var(--accent-mantle);border-color:var(--accent-crust);
    box-shadow:0 0 10px var(--glow-mantle);
  }
  @media(max-width:768px){.nav-dots{display:none}}

  /* ── Sections ── */
  main{position:relative;z-index:1}
  .section{
    min-height:100vh;
    display:flex;align-items:center;justify-content:center;
    padding:4rem 2rem;
  }
  .section-inner{
    max-width:1100px;width:100%;
  }

  /* ── Hero ── */
  .hero{text-align:center;flex-direction:column;gap:2rem}
  .hero h1{
    font-size:clamp(2rem,5vw,3.5rem);font-weight:900;
    background:linear-gradient(135deg,var(--accent-crust),var(--accent-mantle),var(--accent-inner));
    -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
    margin-bottom:.5rem;line-height:1.3;
  }
  .hero .tagline{
    font-size:clamp(1rem,2.5vw,1.4rem);color:var(--text-dim);
    max-width:700px;margin:0 auto;
