  .card.inner-core .stat .value{color:var(--accent-inner)}
  .stat .label{font-size:.75rem;color:var(--text-dim);margin-top:.3rem;display:block}

  /* ── Comparison table ── */
  .table-wrap{
    overflow-x:auto;margin-top:2rem;
