@Composable
private fun ShutterButton(
    isRecording: Boolean,
    isRecordingLocked: Boolean,
    lockDragOffset: Float,
    lockThreshold: Int,
    onToggleVideo: () -> Unit
) {
    Box(
        modifier = Modifier
            .align(Alignment.BottomCenter)
            .padding(bottom = 64.dp),
        contentAlignment = Alignment.Center
    ) {
        if (isRecording && !isRecordingLocked) {
            val density = LocalDensity.current
            val thresholdPx = with(density) { lockThreshold.toPx() }
            val progress = (lockDragOffset / thresholdPx).coerceIn(0f, 1f)

            Box(
                modifier = Modifier
                    .size(80.dp * (1f + progress * 0.6f))
                    .background(Color.Red.copy(alpha = 0.2f + progress * 0.4f), CircleShape)
                    .border(2.dp, Color.White.copy(alpha = 0.3f + progress * 0.5f), CircleShape)
            )
        }

        Box(
            modifier = Modifier
                .size(if (isRecording) 72.dp else 80.dp)
                .background(if (isRecording) Color.Red else Color.White, CircleShape)
                .pointerInput(Unit) {
                    val thresholdPx = lockThreshold.toPx()
                    awaitPointerEventScope {
                        while (true) {
                            val down = awaitFirstDown()

                            if (isRecording) {
                                waitForUpOrCancellation()?.let { onToggleVideo() }
                                continue
                            }

                            val longPressTimeout = viewConfiguration.longPressTimeoutMillis
                            val upChange = withTimeoutOrNull(longPressTimeout) {
                                while (true) {
                                    val event = awaitPointerEvent()
                                    val pointer = event.changes.firstOrNull() ?: break
                                    if (pointer.pressed == false) return@withTimeoutOrNull pointer
                                    pointer.consume()
                                }
                                null
                            }

                            if (upChange == null) {
                                if (!isRecording) {
                                    onToggleVideo()
                                }
                                while (true) {
                                    val event = awaitPointerEvent()
                                    val pointer = event.changes.firstOrNull()
                                    if (pointer == null || pointer.pressed == false) {
                                        if (!isRecordingLocked) onToggleVideo()
                                        break
                                    } else {
                                        val yOffset = down.position.y - pointer.position.y
                                        if (!isRecordingLocked) {
                                            val newOffset = yOffset.coerceAtLeast(0f)
                                            if (newOffset >= thresholdPx) {
                                                break
                                            }
                                        }
                                        pointer.consume()
                                    }
                                }
                            } else {
                                if (!isRecording) onToggleVideo()
                            }
                        }
                    }
                }
        ) {
            if (isRecordingLocked) {
                Icon(Icons.Default.Lock, contentDescription = "Locked", tint = Color.White, modifier = Modifier.size(32.dp).align(Alignment.Center))
            }
        }
    }
}

