private fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val t0 = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()
        bitmap.copyPixelsFromBuffer(byteBuffer)
        val t1 = System.currentTimeMillis()
        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, t1 - t0)
        bitmap.recycle()
        val t2 = System.currentTimeMillis()
        Log.d("MainActivity", "[PERF_CAPTURE] res=${width}x${height} total=${t2 - shutterStartTime}ms wait=${t0 - shutterStartTime}ms copy=${t1 - t0}ms write=${t2 - t1}ms readback=${readbackTime}ms")
    } catch (e: Exception) {
        Log.e("MainActivity", "Background capture failed: ${e.message}", e)
    }
}

private fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,
    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long
) {
    val filename = "LATENT_${metadata.timestamp}.jpg"
    val mimeType = "image/jpeg"
    val contentValues = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
        put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
        put(MediaStore.MediaColumns.RELATIVE_PATH, "DCIM/Camera")
        val now = System.currentTimeMillis()
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / 1000)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / 1000)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
    uri?.let { imageUri ->
        try {
            val t_start = System.currentTimeMillis()
            context.contentResolver.openOutputStream(imageUri)?.use { outputStream ->
                bitmap.compress(Bitmap.CompressFormat.JPEG, 95, outputStream)
            }
            val t_encode = System.currentTimeMillis()

            context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { pfd ->
                val exif = ExifInterface(pfd.fileDescriptor)
                exif.apply {
                    setAttribute(ExifInterface.TAG_MAKE, metadata.make)
                    setAttribute(ExifInterface.TAG_MODEL, metadata.model)
                    setAttribute(ExifInterface.TAG_SOFTWARE, "Latent Camera")
                    setAttribute(ExifInterface.TAG_ARTIST, "Latent Camera")
                    setAttribute(ExifInterface.TAG_FOCAL_LENGTH, "${(metadata.focalLength * 1000).toInt()}/1000")
                    setAttribute(ExifInterface.TAG_F_NUMBER, metadata.aperture.toString())
                    setAttribute(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())
                    val exposureTime = if (metadata.exposureTimeNs > 0) metadata.exposureTimeNs / 1_000_000_000.0 else 0.0
                    setAttribute(ExifInterface.TAG_EXPOSURE_TIME, exposureTime.toString())
                    metadata.location?.let { loc ->
                        setLatLong(loc.latitude, loc.longitude)
                        setGpsInfo(loc)
                    }
                    saveAttributes()
                }
            }
            val t_exif = System.currentTimeMillis()

            contentValues.clear()
            contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
            context.contentResolver.update(imageUri, contentValues, null, null)

            if (BuildConfig.DEBUG) {
                Log.d("MainActivity", "[PERF_STILL] total=${t_exif - shutterStart}ms readback=${readbackTime}ms bitmap=${bitmapTime}ms encode=${t_encode - t_start}ms exif=${t_exif - t_encode}ms")
            }
        } catch (e: Exception) {
            Log.e("MainActivity", "Failed to save image or metadata", e)
            context.mainExecutor.execute {
                Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "—s"

    val exposureTimeSec = exposureTimeNs / 1_000_000_000.0
    val standardSpeeds = mapOf(
        1 to 1.0, 2 to 0.5, 4 to 0.25, 5 to 0.2, 6 to 0.166667,
        10 to 0.1, 15 to 0.066667, 20 to 0.05, 30 to 0.033333,
        60 to 0.016667, 125 to 0.008, 250 to 0.004, 500 to 0.002,
        1000 to 0.001, 2000 to 0.0005, 4000 to 0.00025, 8000 to 0.000125
    )

    var closestDenom = 1
    var minDiff = Double.MAX_VALUE
    for ((denom, _) in standardSpeeds) {
        val diff = Math.abs(exposureTimeSec - 1.0 / denom)
        if (diff < minDiff) {
            minDiff = diff
            closestDenom = denom
        }
    }

    if (minDiff / exposureTimeSec < 0.05) return "1/$closestDenom"

    return when {
        exposureTimeSec >= 1.0 -> "${exposureTimeSec.toInt()}s"
        exposureTimeSec >= 0.01 -> String.format("%.2f", exposureTimeSec) + "s"
        else -> "1/${(1.0 / exposureTimeSec).toInt()}"
    }
}

